// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlersOptions configures RegisterHandlersWithOptions.
type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.DELETE(options.BaseURL+"/api-keys", wrapper.DeleteUserAPIKeys, options.OperationMiddlewares["deleteUserAPIKeys"]...)
	router.GET(options.BaseURL+"/api-keys", wrapper.ListUserAPIKeys, options.OperationMiddlewares["listUserAPIKeys"]...)
	router.POST(options.BaseURL+"/api-keys", wrapper.CreateUserAPIKey, options.OperationMiddlewares["createUserAPIKey"]...)
	router.POST(options.BaseURL+"/marketplace/register", wrapper.RegisterMarketplace, options.OperationMiddlewares["registerMarketplace"]...)
	router.GET(options.BaseURL+"/organizations", wrapper.GetOrganizationsList, options.OperationMiddlewares["getOrganizationsList"]...)
	router.POST(options.BaseURL+"/organizations", wrapper.CreateOrganization, options.OperationMiddlewares["createOrganization"]...)
	router.DELETE(options.BaseURL+"/organizations/:organizationID", wrapper.DeleteOrganization, options.OperationMiddlewares["deleteOrganization"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID", wrapper.GetOrganization, options.OperationMiddlewares["getOrganization"]...)
	router.PUT(options.BaseURL+"/organizations/:organizationID", wrapper.UpdateOrganization, options.OperationMiddlewares["updateOrganization"]...)
	router.DELETE(options.BaseURL+"/organizations/:organizationID/api-keys", wrapper.DeleteOrganizationAPIKeys, options.OperationMiddlewares["deleteOrganizationAPIKeys"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/api-keys", wrapper.ListOrganizationAPIKeys, options.OperationMiddlewares["listOrganizationAPIKeys"]...)
	router.POST(options.BaseURL+"/organizations/:organizationID/api-keys", wrapper.CreateOrganizationAPIKey, options.OperationMiddlewares["createOrganizationAPIKey"]...)
	router.POST(options.BaseURL+"/organizations/:organizationID/billing/checkout-session", wrapper.CreateBillingCheckoutSession, options.OperationMiddlewares["createBillingCheckoutSession"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/billing/customer", wrapper.GetBillingCustomer, options.OperationMiddlewares["getBillingCustomer"]...)
	router.PATCH(options.BaseURL+"/organizations/:organizationID/billing/customer", wrapper.UpdateBillingCustomer, options.OperationMiddlewares["updateBillingCustomer"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/billing/invoices", wrapper.GetBillingInvoices, options.OperationMiddlewares["getBillingInvoices"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/billing/invoices/upcoming", wrapper.GetBillingUpcomingInvoice, options.OperationMiddlewares["getBillingUpcomingInvoice"]...)
	router.POST(options.BaseURL+"/organizations/:organizationID/billing/payment-method-session", wrapper.CreateBillingPaymentMethodSession, options.OperationMiddlewares["createBillingPaymentMethodSession"]...)
	router.POST(options.BaseURL+"/organizations/:organizationID/deletion-request", wrapper.RequestOrganizationDeletion, options.OperationMiddlewares["requestOrganizationDeletion"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/invitations", wrapper.ListOrganizationInvitations, options.OperationMiddlewares["listOrganizationInvitations"]...)
	router.POST(options.BaseURL+"/organizations/:organizationID/invitations", wrapper.CreateOrganizationInvitation, options.OperationMiddlewares["createOrganizationInvitation"]...)
	router.DELETE(options.BaseURL+"/organizations/:organizationID/invitations/:invitationID", wrapper.DeleteOrganizationInvitation, options.OperationMiddlewares["deleteOrganizationInvitation"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/invitations/:invitationID", wrapper.GetOrganizationInvitation, options.OperationMiddlewares["getOrganizationInvitation"]...)
	router.POST(options.BaseURL+"/organizations/:organizationID/invitations/:invitationID/resend", wrapper.ResendOrganizationInvitation, options.OperationMiddlewares["resendOrganizationInvitation"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/members", wrapper.ListOrganizationMembers, options.OperationMiddlewares["listOrganizationMembers"]...)
	router.DELETE(options.BaseURL+"/organizations/:organizationID/members/:userID", wrapper.RemoveOrganizationMember, options.OperationMiddlewares["removeOrganizationMember"]...)
	router.GET(options.BaseURL+"/organizations/:organizationID/membership-limits", wrapper.GetOrganizationMembershipLimits, options.OperationMiddlewares["getOrganizationMembershipLimits"]...)

}

